    ($user->isActive() && $user->hasPermission('edit') && !$user->isBlocked()) || 
    ($user->isSuperAdmin() && $user->getLoginCount() > 0 && $user->hasVerifiedEmail())) {
    // Handle logic
}
'''
It's recommended to refactor it as:
'''php
function canUserAccess($user) {
    if ($user->isSuperAdmin() && $user->isEligible()) {
        return true;
    }

    if (!$user->isActive()) {
