rules.content:
方法的圈复杂度超过推荐的阈值
示例：
'''php
function calculatePrice($product, $user) {
    $price = $product->basePrice;

    if ($user->isVip()) {
        if ($product->isOnSale()) {
            $price *= 0.8;
        } else {
            $price *= 0.9;
        }
    } else if ($product->isOnSale()) {
        if ($user->hasPoints()) {
            $price *= 0.85;
        } else {
            $price *= 0.95;
        }
    } else if ($user->hasPoints()) {
        $price *= 0.97;
    }

    if ($price < $product->minimumPrice) {
        $price = $product->minimumPrice;
    }

    return $price;
}
'''
建议重构为：
'''php
class PriceCalculator {
    private function getVipDiscount($product) {
        return $product->isOnSale() ? 0.8 : 0.9;
    }

    private function getNormalDiscount($product, $user) {
        if ($product->isOnSale()) {
            return $user->hasPoints() ? 0.85 : 0.95;
        }
        return $user->hasPoints() ? 0.97 : 1.0;
    }

    public function calculatePrice($product, $user) {
        $discount = $user->isVip() 
            ? $this->getVipDiscount($product)
            : $this->getNormalDiscount($product, $user);

        $price = $product->basePrice * $discount;
        return max($price, $product->minimumPrice);
    }
}
'''

