在代码库中发现结构相似的代码片段
示例：
'''php
class OrderProcessor {
    public function processNormalOrder($order) {
        $items = $order->getItems();
        $total = 0;
        foreach ($items as $item) {
            $price = $item->getPrice();
            $quantity = $item->getQuantity();
            $total += $price * $quantity;
        }
        return $total;
    }

    public function processWholesaleOrder($order) {
        $items = $order->getItems();
        $total = 0;
        foreach ($items as $item) {
            $price = $item->getWholesalePrice();
            $quantity = $item->getQuantity();
            $total += $price * $quantity * 0.9;
        }
        return $total;
    }
}
'''
建议重构为：
'''php
class OrderProcessor {
    private function calculateTotal($order, $priceStrategy) {
        $total = 0;
        foreach ($order->getItems() as $item) {
            $total += $priceStrategy($item);
        }
        return $total;
    }

    public function processNormalOrder($order) {
        return $this->calculateTotal($order, function($item) {
            return $item->getPrice() * $item->getQuantity();
        });
    }

    public function processWholesaleOrder($order) {
        return $this->calculateTotal($order, function($item) {
            return $item->getWholesalePrice() * $item->getQuantity() * 0.9;
        });
    }
}
'''

